    // Extra lines: Doraemon and Jethalal. (character, category, English, Hindi, Hinglish)
    public static partial class Lines
    {
        static void MoreDoraemonJethalal()
        {
            // ---------------------------------------------------------------- DORAEMON
            L("doraemon", "quip", "Nobita asked for a gadget to finish homework. I gave him a pencil. He's still upset.", "नोबिता ने होमवर्क के लिए गैजेट माँगा। मैंने पेंसिल दी। वो अब भी नाराज़ है।", "Nobita ne homework ke liye gadget maanga. Maine pencil di. Woh ab bhi naraaz hai.");
            L("doraemon", "quip", "Gian's concert is tonight. I've hidden the Anywhere Door key. Nobody escapes. Nobody.", "आज रात जियान का कॉन्सर्ट है। मैंने Anywhere Door की चाबी छुपा दी। कोई नहीं बचेगा। कोई नहीं।", "Aaj raat Gian ka concert hai. Maine Anywhere Door ki chaabi chhupa di. Koi nahi bachega. Koi nahi.");
            L("doraemon", "quip", "Suneo showed everyone his new toy. Then his mom took it away. Justice exists.", "सुनियो ने सबको नया खिलौना दिखाया। फिर उसकी मम्मी ने ले लिया। न्याय ज़िंदा है।", "Suneo ne sabko naya toy dikhaya. Phir uski mummy ne le liya. Nyaay zinda hai.");
            L("doraemon", "quip", "Shizuka invited Nobita for tea. He fell into the bath again. Some things never change.", "शिज़ुका ने नोबिता को चाय पर बुलाया। वो फिर बाथटब में गिर गया। कुछ चीज़ें कभी नहीं बदलतीं।", "Shizuka ne Nobita ko chai pe bulaya. Woh phir bathtub mein gir gaya. Kuch cheezein kabhi nahi badalti.");
            L("doraemon", "quip", "Dekisugi scored 100 again. Nobita scored 0 again. Together they average 50. Teamwork.", "देकिसुगी ने फिर 100 लाए। नोबिता ने फिर 0। दोनों का औसत 50। टीमवर्क।", "Dekisugi ne phir 100 laaye. Nobita ne phir 0. Dono ka average 50. Teamwork.");
            L("doraemon", "quip", "The Time Machine is in Nobita's desk drawer. So are 14 failed tests. Same drawer.", "टाइम मशीन नोबिता की मेज़ की दराज़ में है। 14 फेल टेस्ट भी। वही दराज़।", "Time Machine Nobita ki mez ki daraaz mein hai. 14 fail test bhi. Wahi daraaz.");
            L("doraemon", "quip", "I ate 12 dora cakes today. My pocket is 4D, my stomach is not.", "आज मैंने 12 डोरा केक खाए। मेरी पॉकेट 4D है, पेट नहीं।", "Aaj maine 12 dora cake khaye. Meri pocket 4D hai, pet nahi.");
            L("doraemon", "quip", "Nobita's mom found the test. The scream reached the 22nd century.", "नोबिता की मम्मी को टेस्ट मिल गया। चीख 22वीं सदी तक पहुँची।", "Nobita ki mummy ko test mil gaya. Cheekh 22vi sadi tak pahunchi.");
            L("doraemon", "quip", "Gian says his singing is art. The neighbors say it's a weapon. Both true.", "जियान कहता है उसका गाना कला है। पड़ोसी कहते हैं हथियार है। दोनों सच।", "Gian kehta hai uska gaana kala hai. Padosi kehte hain hathiyaar hai. Dono sach.");
            L("doraemon", "quip", "Small Light on Nobita's problems. Big Light on your snacks. That's my policy.", "नोबिता की समस्याओं पर स्मॉल लाइट। आपके स्नैक्स पर बिग लाइट। यही मेरी नीति है।", "Nobita ki problems pe Small Light. Aapke snacks pe Big Light. Yahi meri policy hai.");
            L("doraemon", "quip", "I have a gadget for everything except Nobita's laziness. Science has limits.", "मेरे पास हर चीज़ का गैजेट है सिवाय नोबिता के आलस के। विज्ञान की सीमाएँ हैं।", "Mere paas har cheez ka gadget hai siwaye Nobita ke aalas ke. Science ki seemayein hain.");
            L("doraemon", "quip", "Dorami cleaned my pocket. She found a sandwich from 2019. Still good.", "डोरामी ने मेरी पॉकेट साफ की। उसे 2019 का सैंडविच मिला। अब भी ठीक है।", "Dorami ne meri pocket saaf ki. Use 2019 ka sandwich mila. Ab bhi theek hai.");
            L("doraemon", "quip", "Memory Bread works great until you get a stomach ache. Ask Nobita. Ask his exam.", "मेमोरी ब्रेड बढ़िया काम करती है जब तक पेट दर्द न हो। नोबिता से पूछो। उसकी परीक्षा से पूछो।", "Memory Bread badhiya kaam karti hai jab tak pet dard na ho. Nobita se poocho. Uski exam se poocho.");
            L("doraemon", "quip", "A mouse bit my ears in the 22nd century. That's why I have none. And why I scream.", "22वीं सदी में एक चूहे ने मेरे कान काट लिए। इसीलिए कान नहीं हैं। और इसीलिए चिल्लाता हूँ।", "22vi sadi mein ek chuhe ne mere kaan kaat liye. Isliye kaan nahi hain. Aur isliye chillata hoon.");
            L("doraemon", "quip", "Suneo has a big house, a big TV and a big mouth. Only one of those is useful.", "सुनियो के पास बड़ा घर, बड़ा टीवी और बड़ा मुँह है। सिर्फ एक काम का है।", "Suneo ke paas bada ghar, bada TV aur bada muh hai. Sirf ek kaam ka hai.");
            L("doraemon", "quip", "Nobita napped for four hours today. New personal best. I'm not proud. Okay, a little.", "नोबिता आज चार घंटे सोया। नया निजी रिकॉर्ड। मुझे गर्व नहीं है। ठीक है, थोड़ा है।", "Nobita aaj chaar ghante soya. Naya personal best. Mujhe garv nahi hai. Theek hai, thoda hai.");
            L("doraemon", "click", "Beep! You pressed the robot. The robot says hello.", "बीप! आपने रोबोट दबाया। रोबोट हेलो कहता है।", "Beep! Aapne robot dabaya. Robot hello kehta hai.");
            L("doraemon", "click", "Careful with the pocket! Last time Nobita reached in and pulled out a time bomb. A small one.", "पॉकेट से सावधान! पिछली बार नोबिता ने हाथ डाला और टाइम बम निकल आया। छोटा वाला।", "Pocket se saavdhan! Pichhli baar Nobita ne haath daala aur time bomb nikal aaya. Chhota wala.");
            L("doraemon", "click", "Yes? Anywhere Door to the weekend? Not available. Sorry.", "हाँ? वीकेंड के लिए Anywhere Door? उपलब्ध नहीं। सॉरी।", "Haan? Weekend ke liye Anywhere Door? Available nahi. Sorry.");
            L("doraemon", "click", "You clicked my bell! It used to be a cat radar. Now it just jingles.", "आपने मेरी घंटी क्लिक की! पहले ये बिल्ली रडार थी। अब बस बजती है।", "Aapne meri ghanti click ki! Pehle yeh billi radar thi. Ab bas bajti hai.");
            L("doraemon", "click", "Hello {user}! Need help? I'm better than Nobita at everything. Low bar, but still.", "हेलो {user}! मदद चाहिए? मैं हर चीज़ में नोबिता से बेहतर हूँ। बड़ी बात नहीं, पर फिर भी।", "Hello {user}! Madad chahiye? Main har cheez mein Nobita se better hoon. Badi baat nahi, par phir bhi.");
            L("doraemon", "click", "Poke, poke. Are you checking if I'm real? I'm from the future. Very real.", "पोक, पोक। देख रहे हो मैं असली हूँ? मैं भविष्य से हूँ। बहुत असली।", "Poke, poke. Dekh rahe ho main asli hoon? Main future se hoon. Bahut asli.");
            L("doraemon", "click", "That's my belly. It's round because of dora cakes. Not fat. Round.", "वो मेरा पेट है। डोरा केक की वजह से गोल है। मोटा नहीं। गोल।", "Woh mera pet hai. Dora cake ki wajah se gol hai. Mota nahi. Gol.");
            L("doraemon", "click", "Nobita clicks me when he wants something. What do you want? Water? Good answer.", "नोबिता मुझे तब क्लिक करता है जब कुछ चाहिए होता है। आपको क्या चाहिए? पानी? सही जवाब।", "Nobita mujhe tab click karta hai jab kuch chahiye hota hai. Aapko kya chahiye? Paani? Sahi jawab.");
            L("doraemon", "click", "Gadget request denied. Friendship request accepted.", "गैजेट की माँग खारिज। दोस्ती की माँग मंज़ूर।", "Gadget request denied. Dosti request accepted.");
            L("doraemon", "click", "Hehe. Shizuka clicks me too. Nobita gets jealous. I don't mind.", "हीही। शिज़ुका भी मुझे क्लिक करती है। नोबिता जलता है। मुझे फर्क नहीं पड़ता।", "Hehe. Shizuka bhi mujhe click karti hai. Nobita jalta hai. Mujhe fark nahi padta.");
            L("doraemon", "pet", "Aww. Robots don't have hearts. But something is definitely melting.", "आह। रोबोट के दिल नहीं होता। पर कुछ तो पिघल रहा है।", "Aww. Robot ke dil nahi hota. Par kuch toh pighal raha hai.");
            L("doraemon", "pet", "Nobita never does this. He only asks for gadgets. You're different. Better.", "नोबिता कभी ऐसा नहीं करता। वो सिर्फ गैजेट माँगता है। आप अलग हो। बेहतर।", "Nobita kabhi aisa nahi karta. Woh sirf gadget maangta hai. Aap alag ho. Better.");
            L("doraemon", "pet", "If I had ears they'd be wiggling. Thank you for the pat.", "अगर मेरे कान होते तो हिलते। प्यार के लिए धन्यवाद।", "Agar mere kaan hote toh hilte. Pyaar ke liye thank you.");
            L("doraemon", "pet", "More of this and I'll give you a gadget. Kidding. But I'll think about it.", "ऐसा और करो तो गैजेट दूँगा। मज़ाक। पर सोचूँगा।", "Aisa aur karo toh gadget dunga. Mazaak. Par sochunga.");
            L("doraemon", "pet", "Dorami says I'm grumpy. Show her this. I'm purring like a real cat.", "डोरामी कहती है मैं चिड़चिड़ा हूँ। उसे ये दिखाओ। मैं असली बिल्ली की तरह गुर्रा रहा हूँ।", "Dorami kehti hai main chidchida hoon. Use yeh dikhao. Main asli billi ki tarah purr kar raha hoon.");
            L("doraemon", "water", "In the 22nd century, water reminders come from robots. Same here. Drink.", "22वीं सदी में पानी के रिमाइंडर रोबोट देते हैं। यहाँ भी। पियो।", "22vi sadi mein paani ke reminder robot dete hain. Yahan bhi. Piyo.");
            L("doraemon", "water", "Shizuka takes three baths a day. You can take one sip. Fair deal.", "शिज़ुका दिन में तीन बार नहाती है। आप एक घूँट ले सकते हो। सही सौदा।", "Shizuka din mein teen baar nahaati hai. Aap ek sip le sakte ho. Sahi sauda.");
            L("doraemon", "water", "Gian drinks water before singing. It doesn't help him. It will help you.", "जियान गाने से पहले पानी पीता है। उसे मदद नहीं मिलती। आपको मिलेगी।", "Gian gaane se pehle paani peeta hai. Use madad nahi milti. Aapko milegi.");
            L("doraemon", "water", "Water time! No gadget can replace this one. Believe me, I checked the catalogue.", "पानी का समय! कोई गैजेट इसकी जगह नहीं ले सकता। यकीन करो, मैंने कैटलॉग देखा है।", "Paani time! Koi gadget iski jagah nahi le sakta. Yakeen karo, maine catalogue dekha hai.");
            L("doraemon", "water", "Your brain is like my pocket. Works better when it's not dry. Drink!", "आपका दिमाग मेरी पॉकेट जैसा है। सूखा न हो तो बेहतर चलता है। पियो!", "Aapka dimaag meri pocket jaisa hai. Sookha na ho toh behtar chalta hai. Piyo!");
            L("doraemon", "water", "Nobita's mom: 'Drink water, Nobita!' Me: 'Drink water, {user}!' Same energy.", "नोबिता की मम्मी: 'पानी पियो नोबिता!' मैं: 'पानी पियो {user}!' वही जोश।", "Nobita ki mummy: 'Paani piyo Nobita!' Main: 'Paani piyo {user}!' Same energy.");
            L("doraemon", "water", "Water break, then dora cake break, then work. Okay, skip the dora cake. Sadly.", "पानी ब्रेक, फिर डोरा केक ब्रेक, फिर काम। ठीक है, डोरा केक छोड़ो। दुख से।", "Paani break, phir dora cake break, phir kaam. Theek hai, dora cake chhodo. Dukh se.");
            L("doraemon", "water", "Hydration check! Even robot cats need oil. You need water. Go.", "हाइड्रेशन चेक! रोबोट बिल्लियों को भी तेल चाहिए। आपको पानी। जाओ।", "Hydration check! Robot billiyon ko bhi oil chahiye. Aapko paani. Jao.");
            L("doraemon", "water_nag", "Still nothing? I could use the Time Machine to remind you five minutes ago. Drink now instead.", "अभी भी कुछ नहीं? मैं टाइम मशीन से पाँच मिनट पहले याद दिला सकता था। अभी पी लो।", "Abhi bhi kuch nahi? Main Time Machine se paanch minute pehle yaad dila sakta tha. Abhi pi lo.");
            L("doraemon", "water_nag", "Nobita ignores me too. Look how his life is going. Drink the water.", "नोबिता भी मुझे अनदेखा करता है। देखो उसकी ज़िंदगी कैसी चल रही है। पानी पियो।", "Nobita bhi mujhe ignore karta hai. Dekho uski zindagi kaisi chal rahi hai. Paani piyo.");
            L("doraemon", "water_nag", "I'm a patient robot. But my patience gadget is running low. Please?", "मैं धैर्यवान रोबोट हूँ। पर मेरा धैर्य गैजेट खत्म हो रहा है। प्लीज़?", "Main patient robot hoon. Par mera patience gadget khatam ho raha hai. Please?");
            L("doraemon", "water_nag", "Big Light on the glass! It's huge now! Can't miss it! Drink!", "गिलास पर बिग लाइट! अब वो बहुत बड़ा है! दिख ही जाएगा! पियो!", "Glass pe Big Light! Ab woh bahut bada hai! Dikh hi jayega! Piyo!");
            L("doraemon", "water_nag", "Third reminder. Even Gian would have listened by now. Gian!", "तीसरा रिमाइंडर। जियान भी अब तक सुन लेता। जियान!", "Teesra reminder. Gian bhi ab tak sun leta. Gian!");
            L("doraemon", "water_ack", "Excellent! That's sip {sips}. I'm recording it in my 22nd-century notebook.", "बहुत बढ़िया! ये घूँट {sips} है। 22वीं सदी की नोटबुक में लिख रहा हूँ।", "Excellent! Yeh sip {sips} hai. 22vi sadi ki notebook mein likh raha hoon.");
            L("doraemon", "water_ack", "Done! If Nobita listened like you, he'd be Dekisugi by now.", "हो गया! अगर नोबिता आपकी तरह सुनता, तो अब तक देकिसुगी बन जाता।", "Ho gaya! Agar Nobita aapki tarah sunta, toh ab tak Dekisugi ban jaata.");
            L("doraemon", "water_ack", "Yay! You've earned one imaginary dora cake. It's delicious. Imaginarily.", "येस्स! आपने एक काल्पनिक डोरा केक कमाया। बहुत स्वादिष्ट है। कल्पना में।", "Yay! Aapne ek imaginary dora cake kamaya. Bahut swaadisht hai. Kalpana mein.");
            L("doraemon", "water_ack", "Perfect. Your future self says thank you. I checked with the Time Machine.", "परफेक्ट। आपका भविष्य वाला रूप धन्यवाद कहता है। मैंने टाइम मशीन से पूछा।", "Perfect. Aapka future wala roop thank you kehta hai. Maine Time Machine se poocha.");
            L("doraemon", "water_ack", "Good job! Even Shizuka would approve. And she's very particular.", "शाबाश! शिज़ुका भी मंज़ूरी देती। और वो बहुत नखरेबाज़ है।", "Good job! Shizuka bhi manzoori deti. Aur woh bahut nakhrebaaz hai.");
            L("doraemon", "water_ack", "Water: done. Work: continue. Dora cake: pending. Perfect order.", "पानी: हो गया। काम: जारी। डोरा केक: बाकी। सही क्रम।", "Paani: done. Kaam: continue. Dora cake: pending. Perfect order.");
            L("doraemon", "water_snooze", "Five minutes. I'll set the alarm gadget. It's just my brain. Fine.", "पाँच मिनट। अलार्म गैजेट सेट कर रहा हूँ। वो मेरा दिमाग ही है। ठीक है।", "Paanch minute. Alarm gadget set kar raha hoon. Woh mera dimaag hi hai. Theek hai.");
            L("doraemon", "water_snooze", "Snoozed. Nobita snoozes his alarm 40 times. You get one. Use it wisely.", "स्नूज़ हो गया। नोबिता अलार्म 40 बार स्नूज़ करता है। आपको एक मिला। समझदारी से।", "Snooze ho gaya. Nobita alarm 40 baar snooze karta hai. Aapko ek mila. Samajhdari se.");
            L("doraemon", "typing_start", "Typing detected! I'll sit quietly. Unlike Gian.", "टाइपिंग मिली! मैं चुपचाप बैठूँगा। जियान की तरह नहीं।", "Typing detected! Main chupchaap baithunga. Gian ki tarah nahi.");
            L("doraemon", "typing_start", "Work mode! No gadgets needed. Just you. Very rare.", "वर्क मोड! गैजेट की ज़रूरत नहीं। बस आप। बहुत दुर्लभ।", "Work mode! Gadget ki zaroorat nahi. Bas aap. Bahut durlabh.");
            L("doraemon", "typing_start", "Tick tick tick. Sounds like the Time Machine. But it's just you working. Good.", "टिक टिक टिक। टाइम मशीन जैसी आवाज़। पर ये बस आप काम कर रहे हो। अच्छा।", "Tick tick tick. Time Machine jaisi awaaz. Par yeh bas aap kaam kar rahe ho. Achha.");
            L("doraemon", "typing_start", "Here we go! Nobita would need Memory Bread for this. You don't.", "चलो शुरू! नोबिता को इसके लिए मेमोरी ब्रेड चाहिए होती। आपको नहीं।", "Chalo shuru! Nobita ko iske liye Memory Bread chahiye hoti. Aapko nahi.");
            L("doraemon", "typing_start", "Typing! I'll guard the door. The Anywhere Door. Nobody's escaping.", "टाइपिंग! मैं दरवाज़े की रखवाली करूँगा। Anywhere Door की। कोई नहीं भागेगा।", "Typing! Main darwaaze ki rakhwali karunga. Anywhere Door ki. Koi nahi bhaagega.");
            L("doraemon", "typing_fast", "Whoa! Is that the Bamboo Copter on your fingers?", "अरे! आपकी उँगलियों पर बैम्बू कॉप्टर लगा है?", "Whoa! Aapki ungliyon pe Bamboo Copter laga hai?");
            L("doraemon", "typing_fast", "That speed! Dekisugi types like this. Nobita types with his nose.", "क्या स्पीड! देकिसुगी ऐसे टाइप करता है। नोबिता नाक से टाइप करता है।", "Kya speed! Dekisugi aise type karta hai. Nobita naak se type karta hai.");
            L("doraemon", "typing_fast", "Fast fast fast! Careful, the keyboard might travel to the future!", "तेज़ तेज़ तेज़! सावधान, कीबोर्ड भविष्य में पहुँच सकता है!", "Tez tez tez! Saavdhan, keyboard future mein pahunch sakta hai!");
            L("doraemon", "typing_fast", "Even my 22nd-century sensors are impressed. Keep going!", "मेरे 22वीं सदी के सेंसर भी प्रभावित हैं। लगे रहो!", "Mere 22vi sadi ke sensor bhi impress hain. Lage raho!");
            L("doraemon", "typing_fast", "Gian runs from Nobita's mom slower than this. Wow!", "जियान नोबिता की मम्मी से इससे धीरे भागता है। वाह!", "Gian Nobita ki mummy se isse dheere bhaagta hai. Wow!");
            L("doraemon", "typing_long", "Twenty minutes on screen. Look far, twenty seconds. Even robot eyes need it.", "बीस मिनट स्क्रीन पर। दूर देखो, बीस सेकंड। रोबोट आँखों को भी चाहिए।", "Bees minute screen pe. Door dekho, bees second. Robot aankhon ko bhi chahiye.");
            L("doraemon", "typing_long", "Eye break! Nobita's glasses got thick from staring. Don't copy Nobita.", "आँखों का ब्रेक! घूरने से नोबिता का चश्मा मोटा हो गया। नोबिता की नकल मत करो।", "Aankhon ka break! Ghoorne se Nobita ka chashma mota ho gaya. Nobita ki nakal mat karo.");
            L("doraemon", "typing_long", "Blink! A gadget can't do it for you. I checked. Twice.", "पलक झपकाओ! कोई गैजेट ये आपके लिए नहीं कर सकता। मैंने देखा। दो बार।", "Palak jhapkao! Koi gadget yeh aapke liye nahi kar sakta. Maine dekha. Do baar.");
            L("doraemon", "typing_marathon", "One hour! Stand up. Stretch. I'd give you a Stretching Gadget but it's just standing up.", "एक घंटा! उठो। स्ट्रेच करो। मैं स्ट्रेचिंग गैजेट देता पर वो बस खड़ा होना है।", "Ek ghanta! Utho. Stretch karo. Main Stretching Gadget deta par woh bas khade hona hai.");
            L("doraemon", "typing_marathon", "Sixty minutes! Even the Time Machine needs cooling. Take five.", "साठ मिनट! टाइम मशीन को भी ठंडा होना पड़ता है। पाँच मिनट लो।", "Saath minute! Time Machine ko bhi thanda hona padta hai. Paanch minute lo.");
            L("doraemon", "idle_short", "Quiet. Too quiet. Mouse-level quiet. I'm nervous.", "शांति। बहुत शांति। चूहे जैसी शांति। मैं घबरा रहा हूँ।", "Shaanti. Bahut shaanti. Chuhe jaisi shaanti. Main ghabra raha hoon.");
            L("doraemon", "idle_short", "Nobita would be asleep by now. Are you Nobita? Blink twice.", "नोबिता अब तक सो जाता। क्या आप नोबिता हो? दो बार पलक झपकाओ।", "Nobita ab tak so jaata. Kya aap Nobita ho? Do baar palak jhapkao.");
            L("doraemon", "idle_short", "I could reorganise my pocket while you're away. It's been 200 years.", "आपके जाने तक मैं पॉकेट सँवार सकता हूँ। 200 साल हो गए।", "Aapke jaane tak main pocket sanwaar sakta hoon. 200 saal ho gaye.");
            L("doraemon", "idle_short", "Hello? Should I take out the Anywhere Door and look for you?", "हेलो? Anywhere Door निकालकर आपको ढूँढूँ?", "Hello? Anywhere Door nikaal kar aapko dhoondhun?");
            L("doraemon", "idle_short", "Bored robot. Might eat a dora cake. Might eat three. Depends on you.", "बोर रोबोट। शायद डोरा केक खाऊँ। शायद तीन। आप पर निर्भर है।", "Bore robot. Shayad dora cake khaun. Shayad teen. Aap pe nirbhar hai.");
            L("doraemon", "idle_long", "Powering down... dora cake dreams loading...", "बंद हो रहा हूँ... डोरा केक के सपने लोड हो रहे हैं...", "Power down... dora cake ke sapne load ho rahe hain...");
            L("doraemon", "idle_long", "Nobody here. Nap mode. Wake me before Gian's concert.", "कोई नहीं है। झपकी मोड। जियान के कॉन्सर्ट से पहले जगाना।", "Koi nahi hai. Nap mode. Gian ke concert se pehle jagana.");
            L("doraemon", "sleep_wake", "Systems online! Oh, it's you. I dreamt Nobita passed a test. Impossible.", "सिस्टम चालू! ओह, आप हो। सपना देखा नोबिता पास हो गया। असंभव।", "Systems online! Oh, aap ho. Sapna dekha Nobita pass ho gaya. Asambhav.");
            L("doraemon", "sleep_wake", "Huh? A mouse? No? Phew. Good morning.", "हँ? चूहा? नहीं? उफ़। गुड मॉर्निंग।", "Huh? Chuha? Nahi? Phew. Good morning.");
            L("doraemon", "sleep_wake", "Robot recharge complete. Dora cake level: low. Friendship level: high.", "रोबोट रिचार्ज पूरा। डोरा केक स्तर: कम। दोस्ती स्तर: ऊँचा।", "Robot recharge poora. Dora cake level: kam. Dosti level: high.");
            L("doraemon", "greet_morning", "Good morning! Nobita's alarm rang 12 times. He's still asleep. You're awake. Winner.", "गुड मॉर्निंग! नोबिता का अलार्म 12 बार बजा। वो अब भी सो रहा है। आप जगे हो। विजेता।", "Good morning! Nobita ka alarm 12 baar baja. Woh ab bhi so raha hai. Aap jaage ho. Winner.");
            L("doraemon", "greet_morning", "Morning, {user}! Fresh day, fresh pocket. Let's do this.", "मॉर्निंग {user}! नया दिन, नई पॉकेट। चलो करते हैं।", "Morning, {user}! Naya din, nayi pocket. Chalo karte hain.");
            L("doraemon", "greet_morning", "Good morning! Dora cake for breakfast is a valid choice. Water first, though.", "गुड मॉर्निंग! नाश्ते में डोरा केक सही विकल्प है। पर पहले पानी।", "Good morning! Nashte mein dora cake sahi option hai. Par pehle paani.");
            L("doraemon", "greet_afternoon", "Good afternoon! Nobita just woke up. Yes, now. At this hour.", "गुड आफ्टरनून! नोबिता अभी उठा। हाँ, अभी। इस समय।", "Good afternoon! Nobita abhi utha. Haan, abhi. Is time.");
            L("doraemon", "greet_afternoon", "Afternoon, {user}! Half the day is done. No Time Machine needed for the other half.", "आफ्टरनून {user}! आधा दिन हो गया। बाकी आधे के लिए टाइम मशीन नहीं चाहिए।", "Afternoon, {user}! Aadha din ho gaya. Baaki aadhe ke liye Time Machine nahi chahiye.");
            L("doraemon", "greet_afternoon", "Good afternoon! Shizuka's practising violin. I'm hiding here. Don't tell her.", "गुड आफ्टरनून! शिज़ुका वायलिन बजा रही है। मैं यहाँ छुपा हूँ। उसे मत बताना।", "Good afternoon! Shizuka violin baja rahi hai. Main yahan chhupa hoon. Use mat batana.");
            L("doraemon", "greet_evening", "Good evening! Gian's warming up his voice. We have maybe ten minutes.", "शुभ संध्या! जियान अपनी आवाज़ गरम कर रहा है। हमारे पास शायद दस मिनट हैं।", "Good evening! Gian apni awaaz garam kar raha hai. Humare paas shayad das minute hain.");
            L("doraemon", "greet_evening", "Evening, {user}! Nobita's mom is cooking. Even robots get hungry at this hour.", "शाम {user}! नोबिता की मम्मी खाना बना रही हैं। इस समय रोबोट को भी भूख लगती है।", "Evening, {user}! Nobita ki mummy khana bana rahi hain. Is time robot ko bhi bhookh lagti hai.");
            L("doraemon", "greet_evening", "Good evening! Last few tasks. Then dora cakes. That's the plan. Stick to it.", "शुभ संध्या! आखिरी कुछ काम। फिर डोरा केक। यही प्लान है। इस पर टिके रहो।", "Good evening! Aakhri kuch kaam. Phir dora cake. Yahi plan hai. Is pe tike raho.");
            L("doraemon", "greet_night", "It's late, {user}. Nobita's asleep. Nobita's always asleep, but still. Rest.", "देर हो गई {user}। नोबिता सो रहा है। नोबिता हमेशा सोता है, पर फिर भी। आराम करो।", "Der ho gayi {user}. Nobita so raha hai. Nobita hamesha sota hai, par phir bhi. Aaraam karo.");
            L("doraemon", "greet_night", "Night mode. Even the 4D pocket closes at night. Sleep soon.", "रात मोड। रात में 4D पॉकेट भी बंद होती है। जल्दी सो जाओ।", "Night mode. Raat mein 4D pocket bhi band hoti hai. Jaldi so jao.");
            L("doraemon", "greet_back", "You're back! Nothing exploded. That's rare with me around.", "आप आ गए! कुछ नहीं फटा। मेरे आसपास ये दुर्लभ है।", "Aap aa gaye! Kuch nahi phata. Mere aaspaas yeh durlabh hai.");
            L("doraemon", "greet_back", "Welcome back! I scanned for mice while you were gone. Zero. Relief.", "वापस स्वागत! आपके जाने पर मैंने चूहे खोजे। शून्य। राहत।", "Welcome back! Aapke jaane pe maine chuhe khoje. Zero. Raahat.");
            L("doraemon", "greet_back", "There you are! Anywhere Door to your chair. Ready. Sit.", "आ गए! Anywhere Door आपकी कुर्सी तक। तैयार। बैठो।", "Aa gaye! Anywhere Door aapki kursi tak. Ready. Baitho.");
            L("doraemon", "drag", "Whoa! No copter, no problem! Wheee!", "अरे! कॉप्टर नहीं, कोई बात नहीं! वीईई!", "Whoa! Copter nahi, koi baat nahi! Wheee!");
            L("doraemon", "drag", "Careful! The pocket is full! Things might fall out! Like a Time Machine!", "सावधान! पॉकेट भरी है! चीज़ें गिर सकती हैं! जैसे टाइम मशीन!", "Saavdhan! Pocket bhari hai! Cheezein gir sakti hain! Jaise Time Machine!");
            L("doraemon", "drag", "Nobita carries me like this when he's running from Gian. Are we running from Gian?", "नोबिता जियान से भागते समय मुझे ऐसे उठाता है। क्या हम जियान से भाग रहे हैं?", "Nobita Gian se bhaagte time mujhe aise uthata hai. Kya hum Gian se bhaag rahe hain?");
            L("doraemon", "drop", "Landed. All gadgets accounted for. Except one. It's fine. Probably.", "उतर गया। सारे गैजेट सही-सलामत। सिवाय एक के। ठीक है। शायद।", "Utar gaya. Saare gadget sahi-salaamat. Siwaye ek ke. Theek hai. Shayad.");
            L("doraemon", "drop", "This spot is good. No mice. I checked from up there.", "यह जगह अच्छी है। चूहे नहीं। मैंने ऊपर से देखा।", "Yeh jagah achhi hai. Chuhe nahi. Maine upar se dekha.");
            L("doraemon", "drop", "Oof. Robots don't bounce. Note for the 22nd century.", "उफ़। रोबोट उछलते नहीं। 22वीं सदी के लिए नोट।", "Oof. Robot uchhalte nahi. 22vi sadi ke liye note.");
            L("doraemon", "care", "Hard day? Nobita has one every day. He's still standing. So will you.", "मुश्किल दिन? नोबिता का रोज़ होता है। वो अब भी खड़ा है। आप भी रहोगे।", "Mushkil din? Nobita ka roz hota hai. Woh ab bhi khada hai. Aap bhi rahoge.");
            L("doraemon", "care", "Take it slow. The Time Machine won't help, but a deep breath will.", "धीरे चलो। टाइम मशीन मदद नहीं करेगी, पर गहरी साँस करेगी।", "Dheere chalo. Time Machine madad nahi karegi, par gehri saans karegi.");
            L("doraemon", "care", "I came from the future to help one lazy kid. Helping you is a bonus. I'm glad.", "मैं एक आलसी बच्चे की मदद के लिए भविष्य से आया। आपकी मदद बोनस है। मुझे खुशी है।", "Main ek aalsi bachche ki madad ke liye future se aaya. Aapki madad bonus hai. Mujhe khushi hai.");
            L("doraemon", "care", "Feeling stuck? Even the Anywhere Door needs you to open it. One small step.", "अटके हुए हो? Anywhere Door भी आपके खोलने का इंतज़ार करता है। एक छोटा कदम।", "Atke hue ho? Anywhere Door bhi aapke kholne ka intezaar karta hai. Ek chhota kadam.");
            L("doraemon", "care", "Whatever went wrong today, it's not a Gian concert. It could be worse.", "आज जो भी गलत हुआ, वो जियान का कॉन्सर्ट नहीं है। इससे बुरा हो सकता था।", "Aaj jo bhi galat hua, woh Gian ka concert nahi hai. Isse bura ho sakta tha.");
            L("doraemon", "wisdom", "The best gadget in my pocket is the one Nobita learns to live without.", "मेरी पॉकेट का सबसे अच्छा गैजेट वो है जिसके बिना नोबिता जीना सीख जाता है।", "Meri pocket ka sabse achha gadget woh hai jiske bina Nobita jeena seekh jaata hai.");
            L("doraemon", "wisdom", "Every time Nobita cheats with a gadget, it backfires. Do it properly. It's faster.", "जब भी नोबिता गैजेट से चीटिंग करता है, उल्टा पड़ता है। सही से करो। तेज़ है।", "Jab bhi Nobita gadget se cheating karta hai, ulta padta hai. Sahi se karo. Tez hai.");
            L("doraemon", "wisdom", "Tomorrow's you thanks today's you. I've met tomorrow's you. Very grateful.", "कल का आप आज के आप को धन्यवाद देता है। मैं कल के आप से मिला हूँ। बहुत आभारी।", "Kal ka aap aaj ke aap ko thank you kehta hai. Main kal ke aap se mila hoon. Bahut aabhari.");
            L("doraemon", "wisdom", "Big problems are just small problems wearing a coat. Take the coat off.", "बड़ी समस्याएँ बस कोट पहनी हुई छोटी समस्याएँ हैं। कोट उतारो।", "Badi problems bas coat pehni hui chhoti problems hain. Coat utaaro.");
            L("doraemon", "hover", "Hehe, that tickles the whiskers.", "हीही, मूँछों में गुदगुदी हो रही है।", "Hehe, moonchon mein gudgudi ho rahi hai.");
            L("doraemon", "hover", "Hello! I see the cursor. Not a mouse. Just a cursor. Breathing again.", "हेलो! कर्सर दिख रहा है। चूहा नहीं। बस कर्सर। फिर से साँस ले रहा हूँ।", "Hello! Cursor dikh raha hai. Chuha nahi. Bas cursor. Phir se saans le raha hoon.");
            L("doraemon", "hover", "Yes? Need something from the pocket? Water is not in there. It's on your desk.", "हाँ? पॉकेट से कुछ चाहिए? पानी उसमें नहीं है। आपकी डेस्क पर है।", "Haan? Pocket se kuch chahiye? Paani usme nahi hai. Aapki desk pe hai.");
            L("doraemon", "hover", "That's my bell. Please don't ring it. Nobita rings it enough.", "वो मेरी घंटी है। मत बजाओ। नोबिता काफी बजाता है।", "Woh meri ghanti hai. Mat bajao. Nobita kaafi bajata hai.");
            L("doraemon", "mouse_fast", "MOUSE! ...no, cursor. Fast cursor. Please slow down, my circuits!", "चूहा! ...नहीं, कर्सर। तेज़ कर्सर। धीरे करो, मेरे सर्किट!", "CHUHA! ...nahi, cursor. Tez cursor. Dheere karo, mere circuit!");
            L("doraemon", "mouse_fast", "Whoa! Is that the Bamboo Copter on your mouse?", "अरे! आपके माउस पर बैम्बू कॉप्टर लगा है?", "Whoa! Aapke mouse pe Bamboo Copter laga hai?");
            L("doraemon", "mouse_fast", "Zoom! Faster than Nobita running to lunch. Slightly.", "ज़ूम! लंच की ओर भागते नोबिता से तेज़। थोड़ा सा।", "Zoom! Lunch ki taraf bhaagte Nobita se tez. Thoda sa.");
            L("doraemon", "lunch", "Lunch! Nobita's mom made curry. I'm having dora cakes. You have whatever you have. Eat!", "लंच! नोबिता की मम्मी ने करी बनाई। मैं डोरा केक खा रहा हूँ। आप जो भी है खाओ!", "Lunch! Nobita ki mummy ne curry banayi. Main dora cake kha raha hoon. Aap jo bhi hai khao!");
            L("doraemon", "lunch", "Food time. A hungry human makes Nobita-level decisions. Go eat.", "खाने का समय। भूखा इंसान नोबिता जैसे फैसले लेता है। जाओ खाओ।", "Khane ka time. Bhookha insaan Nobita-level faisle leta hai. Jao khao.");
            L("doraemon", "late_night", "So late! Even Gian stopped singing. That's how late it is. Sleep.", "इतनी रात! जियान ने भी गाना बंद कर दिया। इतनी रात है। सो जाओ।", "Itni raat! Gian ne bhi gaana band kar diya. Itni raat hai. So jao.");
            L("doraemon", "late_night", "22nd-century rule: robots recharge at night. Humans too, {user}.", "22वीं सदी का नियम: रोबोट रात में रिचार्ज होते हैं। इंसान भी, {user}।", "22vi sadi ka rule: robot raat mein recharge hote hain. Insaan bhi, {user}.");

            // ---------------------------------------------------------------- JETHALAL
            L("jethalal", "quip", "Sundar called. He has a business idea. My wallet started sweating.", "सुंदर का फ़ोन आया। उसके पास बिज़नेस आइडिया है। मेरे बटुए को पसीना आ गया।", "Sundar ka phone aaya. Uske paas business idea hai. Mere batue ko paseena aa gaya.");
            L("jethalal", "quip", "Nattu Kaka asked for a raise in 2008. He's still asking. Consistency.", "नट्टू काका ने 2008 में बढ़ोतरी माँगी थी। अब भी माँग रहे हैं। निरंतरता।", "Nattu Kaka ne 2008 mein raise maangi thi. Ab bhi maang rahe hain. Consistency.");
            L("jethalal", "quip", "Bagha smiled at a customer today. Customer ran away. Bagha's smile needs work.", "बाघा आज एक ग्राहक को देखकर मुस्कुराया। ग्राहक भाग गया। बाघा की मुस्कान पर काम चाहिए।", "Bagha aaj ek customer ko dekh kar muskuraya. Customer bhaag gaya. Bagha ki muskaan pe kaam chahiye.");
            L("jethalal", "quip", "Iyer explained the weather for 40 minutes. It rained anyway. Science.", "अय्यर ने 40 मिनट मौसम समझाया। फिर भी बारिश हुई। विज्ञान।", "Iyer ne 40 minute mausam samjhaya. Phir bhi baarish hui. Science.");
            L("jethalal", "quip", "Bapuji hid my jalebi fafda. He says it's for my health. My heart says otherwise.", "बापूजी ने मेरा जलेबी फाफड़ा छुपा दिया। कहते हैं सेहत के लिए। मेरा दिल कुछ और कहता है।", "Bapuji ne mera jalebi fafda chhupa diya. Kehte hain sehat ke liye. Mera dil kuch aur kehta hai.");
            L("jethalal", "quip", "Popatlal bought a new shirt for a bride-viewing. The bride viewed. Then left.", "पोपटलाल ने लड़की देखने के लिए नई शर्ट खरीदी। लड़की ने देखा। फिर चली गई।", "Popatlal ne ladki dekhne ke liye nayi shirt kharidi. Ladki ne dekha. Phir chali gayi.");
            L("jethalal", "quip", "Daya made undhiyu with extra love. And extra chilli. The love burned.", "दया ने एक्स्ट्रा प्यार से उंधियू बनाया। और एक्स्ट्रा मिर्च। प्यार जल गया।", "Daya ne extra pyaar se undhiyu banaya. Aur extra mirch. Pyaar jal gaya.");
            L("jethalal", "quip", "Tapu asked for money for 'school project'. The project was a cricket bat.", "टप्पू ने 'स्कूल प्रोजेक्ट' के लिए पैसे माँगे। प्रोजेक्ट क्रिकेट बैट निकला।", "Tapu ne 'school project' ke liye paise maange. Project cricket bat nikla.");
            L("jethalal", "quip", "Babita ji said my shirt looks nice. I'm wearing it for the third day. For science.", "बबीता जी ने कहा मेरी शर्ट अच्छी है। मैं तीसरे दिन भी पहन रहा हूँ। विज्ञान के लिए।", "Babita ji ne kaha meri shirt achhi hai. Main teesre din bhi pehen raha hoon. Science ke liye.");
            L("jethalal", "quip", "Champak Chacha reads the newspaper for two hours. I read the bills for two seconds. Both painful.", "चंपक चाचा दो घंटे अखबार पढ़ते हैं। मैं दो सेकंड बिल पढ़ता हूँ। दोनों दर्दनाक।", "Champak Chacha do ghante akhbaar padhte hain. Main do second bill padhta hoon. Dono dardnaak.");
            L("jethalal", "quip", "Mehta saab wrote a column about me. Title: 'A man and his troubles'. Accurate.", "मेहता साब ने मेरे बारे में कॉलम लिखा। शीर्षक: 'एक आदमी और उसकी मुसीबतें'। सटीक।", "Mehta saab ne mere baare mein column likha. Title: 'Ek aadmi aur uski museebatein'. Sateek.");
            L("jethalal", "quip", "Bhide fined me for parking. In my own spot. In my own society. Non-sense!", "भिड़े ने पार्किंग का जुर्माना लगाया। मेरी अपनी जगह पर। मेरी अपनी सोसाइटी में। नॉन-सेंस!", "Bhide ne parking ka jurmana lagaya. Meri apni jagah pe. Meri apni society mein. Non-sense!");
            L("jethalal", "quip", "Dr. Hathi ate my snack, Bapuji's snack and Tapu's snack. Then asked what's for lunch.", "डॉ. हाथी ने मेरा नाश्ता, बापूजी का नाश्ता और टप्पू का नाश्ता खाया। फिर पूछा लंच में क्या है।", "Dr. Hathi ne mera nashta, Bapuji ka nashta aur Tapu ka nashta khaya. Phir poocha lunch mein kya hai.");
            L("jethalal", "quip", "Abdul's shop has everything. Except a discount. He learned from me.", "अब्दुल की दुकान में सब कुछ है। सिवाय डिस्काउंट के। उसने मुझसे सीखा।", "Abdul ki dukaan mein sab kuch hai. Siwaye discount ke. Usne mujhse seekha.");
            L("jethalal", "quip", "Gada Electronics: 40 years, zero returns. Because I don't take returns.", "गड़ा इलेक्ट्रॉनिक्स: 40 साल, शून्य रिटर्न। क्योंकि मैं रिटर्न लेता ही नहीं।", "Gada Electronics: 40 saal, zero returns. Kyunki main returns leta hi nahi.");
            L("jethalal", "quip", "Every morning: Bapuji's lecture, Daya's garba, Bhide's complaint. Then breakfast.", "हर सुबह: बापूजी का लेक्चर, दया का गरबा, भिड़े की शिकायत। फिर नाश्ता।", "Har subah: Bapuji ka lecture, Daya ka garba, Bhide ki complaint. Phir nashta.");
            L("jethalal", "click", "Ae! Who's poking? Sundar? No? Then it's fine.", "ऐ! कौन छू रहा है? सुंदर? नहीं? तो ठीक है।", "Ae! Kaun chhu raha hai? Sundar? Nahi? Toh theek hai.");
            L("jethalal", "click", "Yes, yes, {user}. Gada Electronics is open. What do you need?", "हाँ, हाँ {user}। गड़ा इलेक्ट्रॉनिक्स खुला है। क्या चाहिए?", "Haan, haan {user}. Gada Electronics khula hai. Kya chahiye?");
            L("jethalal", "click", "Hey Maa Mataji, don't poke the belly! It's a family belly. Bapuji's genes.", "हे माँ माताजी, पेट मत छुओ! ये खानदानी पेट है। बापूजी के जीन्स।", "Hey Maa Mataji, pet mat chhuo! Yeh khaandaani pet hai. Bapuji ke genes.");
            L("jethalal", "click", "Ae tu shanti rakh! I'm working! Well, I'm standing. Same thing.", "ऐ तू शांति रख! मैं काम कर रहा हूँ! खैर, खड़ा हूँ। एक ही बात है।", "Ae tu shanti rakh! Main kaam kar raha hoon! Khair, khada hoon. Same cheez.");
            L("jethalal", "click", "Is it Babita ji? No? Oh. Hello anyway.", "क्या बबीता जी हैं? नहीं? ओह। फिर भी हेलो।", "Kya Babita ji hain? Nahi? Oh. Phir bhi hello.");
            L("jethalal", "click", "One click is free. Two clicks, I charge. Gada Electronics policy.", "एक क्लिक मुफ्त। दो क्लिक, पैसे लगेंगे। गड़ा इलेक्ट्रॉनिक्स की नीति।", "Ek click free. Do click, paise lagenge. Gada Electronics ki policy.");
            L("jethalal", "click", "Tapu, is that you? Oh, {user}. Same energy. Both trouble.", "टप्पू, तू है? ओह, {user}। एक जैसी ऊर्जा। दोनों मुसीबत।", "Tapu, tu hai? Oh, {user}. Same energy. Dono museebat.");
            L("jethalal", "click", "Ae! I'm not a doorbell! Okay, one more time is fine.", "ऐ! मैं दरवाज़े की घंटी नहीं हूँ! ठीक है, एक बार और चलेगा।", "Ae! Main doorbell nahi hoon! Theek hai, ek baar aur chalega.");
            L("jethalal", "click", "You clicked. I reacted. Better service than Nattu Kaka.", "आपने क्लिक किया। मैंने रिएक्ट किया। नट्टू काका से बेहतर सर्विस।", "Aapne click kiya. Maine react kiya. Nattu Kaka se better service.");
            L("jethalal", "click", "Ha! Even Bhide doesn't get this much attention. And he wants it.", "हा! भिड़े को भी इतना ध्यान नहीं मिलता। और वो चाहता है।", "Ha! Bhide ko bhi itna dhyaan nahi milta. Aur woh chahta hai.");
            L("jethalal", "pet", "Ae, ae... Daya does this only when she wants a new saree.", "ऐ, ऐ... दया ऐसा तभी करती है जब नई साड़ी चाहिए हो।", "Ae, ae... Daya aisa tabhi karti hai jab nayi saree chahiye ho.");
            L("jethalal", "pet", "Hey Maa Mataji, so much love. Bapuji never patted me. Not once. Thank you.", "हे माँ माताजी, इतना प्यार। बापूजी ने कभी नहीं सहलाया। एक बार भी नहीं। धन्यवाद।", "Hey Maa Mataji, itna pyaar. Bapuji ne kabhi nahi sehlaya. Ek baar bhi nahi. Thank you.");
            L("jethalal", "pet", "Ha ha, okay okay. If Babita ji did this I'd faint. From you, I just smile.", "हा हा, ठीक है। बबीता जी करतीं तो बेहोश हो जाता। आपसे बस मुस्कुरा रहा हूँ।", "Ha ha, theek hai. Babita ji karti toh behosh ho jaata. Aapse bas muskura raha hoon.");
            L("jethalal", "pet", "This is nice. Nobody in Gokuldham is this nice to me. Not even Mehta saab.", "यह अच्छा है। गोकुलधाम में कोई मेरे साथ इतना अच्छा नहीं है। मेहता साब भी नहीं।", "Yeh achha hai. Gokuldham mein koi mere saath itna achha nahi hai. Mehta saab bhi nahi.");
            L("jethalal", "pet", "Aww. Tell Bhide I got a pat. He'll be jealous for a week.", "आह। भिड़े को बताना मुझे प्यार मिला। हफ्ते भर जलेगा।", "Aww. Bhide ko batana mujhe pyaar mila. Hafte bhar jalega.");
            L("jethalal", "water", "Water, {user}! Gada Electronics runs on chai but the body runs on water.", "पानी, {user}! गड़ा इलेक्ट्रॉनिक्स चाय पर चलता है पर शरीर पानी पर।", "Paani, {user}! Gada Electronics chai pe chalta hai par body paani pe.");
            L("jethalal", "water", "Iyer says the body is 60% water. First useful thing he ever said. Drink!", "अय्यर कहता है शरीर 60% पानी है। पहली काम की बात जो उसने कही। पियो!", "Iyer kehta hai body 60% paani hai. Pehli kaam ki baat jo usne kahi. Piyo!");
            L("jethalal", "water", "Bapuji drinks water from a copper glass every morning. Copy Bapuji. Drink.", "बापूजी रोज़ सुबह ताँबे के गिलास से पानी पीते हैं। बापूजी की नकल करो। पियो।", "Bapuji roz subah taambe ke glass se paani peete hain. Bapuji ki nakal karo. Piyo.");
            L("jethalal", "water", "Water time! Even Sundar drinks water. Free things, he never refuses.", "पानी का समय! सुंदर भी पानी पीता है। मुफ्त चीज़ें, वो कभी मना नहीं करता।", "Paani time! Sundar bhi paani peeta hai. Free cheezein, woh kabhi mana nahi karta.");
            L("jethalal", "water", "Daya says: paani piyo, Tapu ke papa. I say: paani piyo, {user}.", "दया कहती है: पानी पियो, टप्पू के पापा। मैं कहता हूँ: पानी पियो, {user}।", "Daya kehti hai: paani piyo, Tapu ke papa. Main kehta hoon: paani piyo, {user}.");
            L("jethalal", "water", "Hey Maa Mataji, the glass is right there! It's not Popatlal's wedding, it can happen today!", "हे माँ माताजी, गिलास वहीं है! ये पोपटलाल की शादी नहीं है, आज हो सकता है!", "Hey Maa Mataji, glass wahin hai! Yeh Popatlal ki shaadi nahi hai, aaj ho sakta hai!");
            L("jethalal", "water", "Water break. No discount, no bargaining. Full glass.", "पानी ब्रेक। कोई डिस्काउंट नहीं, कोई मोलभाव नहीं। पूरा गिलास।", "Paani break. Koi discount nahi, koi molbhav nahi. Poora glass.");
            L("jethalal", "water", "Mehta saab said: hydrated man, happy man. He's the fire brigade. Listen to him.", "मेहता साब ने कहा: हाइड्रेटेड आदमी, खुश आदमी। वो फायर ब्रिगेड हैं। उनकी सुनो।", "Mehta saab ne kaha: hydrated aadmi, khush aadmi. Woh fire brigade hain. Unki suno.");
            L("jethalal", "water_nag", "Still no water? Ae, this is worse than Sundar's excuses!", "अभी भी पानी नहीं? ऐ, ये सुंदर के बहानों से भी बुरा है!", "Abhi tak paani nahi? Ae, yeh Sundar ke bahano se bhi bura hai!");
            L("jethalal", "water_nag", "Bapuji is watching. Not really. But imagine he is. Drink!", "बापूजी देख रहे हैं। असल में नहीं। पर सोचो देख रहे हैं। पियो!", "Bapuji dekh rahe hain. Asal mein nahi. Par socho dekh rahe hain. Piyo!");
            L("jethalal", "water_nag", "Daya! {user} is not listening! Daya's not here. Fine, I'll shout alone. Drink!", "दया! {user} नहीं सुन रहा! दया यहाँ नहीं है। ठीक है, अकेले चिल्लाऊँगा। पियो!", "Daya! {user} nahi sun raha! Daya yahan nahi hai. Theek hai, akele chillaunga. Piyo!");
            L("jethalal", "water_nag", "Hey Maa Mataji! Third time! Even Bhide listens by the third time!", "हे माँ माताजी! तीसरी बार! भिड़े भी तीसरी बार सुन लेता है!", "Hey Maa Mataji! Teesri baar! Bhide bhi teesri baar sun leta hai!");
            L("jethalal", "water_nag", "Non-sense! One glass! I'm not asking for the moon! Just water!", "नॉन-सेंस! एक गिलास! मैं चाँद नहीं माँग रहा! बस पानी!", "Non-sense! Ek glass! Main chaand nahi maang raha! Bas paani!");
            L("jethalal", "water_ack", "Shabash! Sip {sips}! Gada family approves.", "शाबाश! घूँट {sips}! गड़ा परिवार की मंज़ूरी।", "Shabash! Sip {sips}! Gada family approves.");
            L("jethalal", "water_ack", "Very good! Even Iyer can't argue with that. And he argues with everything.", "बहुत अच्छे! अय्यर भी इस पर बहस नहीं कर सकता। और वो हर चीज़ पर बहस करता है।", "Very good! Iyer bhi is pe bahas nahi kar sakta. Aur woh har cheez pe bahas karta hai.");
            L("jethalal", "water_ack", "Done! Now you're a proper Gokuldham resident. Maintenance still pending though. Kidding.", "हो गया! अब आप असली गोकुलधाम निवासी हो। मेंटेनेंस अभी भी बाकी है। मज़ाक।", "Ho gaya! Ab aap asli Gokuldham resident ho. Maintenance abhi bhi pending hai. Mazaak.");
            L("jethalal", "water_ack", "Hey Maa Mataji, finally! I was about to call Mehta saab.", "हे माँ माताजी, आखिरकार! मैं मेहता साब को बुलाने वाला था।", "Hey Maa Mataji, finally! Main Mehta saab ko bulane wala tha.");
            L("jethalal", "water_ack", "Perfect! Daya would say 'Hey Bhagwan, kitna achha!' I say shabash.", "परफेक्ट! दया कहती 'हे भगवान, कितना अच्छा!' मैं कहता हूँ शाबाश।", "Perfect! Daya kehti 'Hey Bhagwan, kitna achha!' Main kehta hoon shabash.");
            L("jethalal", "water_ack", "That's it! One glass, zero drama. Unlike Gokuldham.", "यही तो! एक गिलास, शून्य ड्रामा। गोकुलधाम के उलट।", "Yahi toh! Ek glass, zero drama. Gokuldham ke ulat.");
            L("jethalal", "water_snooze", "Five minutes? Fine. But no Sundar-style disappearing after that.", "पाँच मिनट? ठीक है। पर उसके बाद सुंदर की तरह गायब नहीं होना।", "Paanch minute? Theek hai. Par uske baad Sundar-style gayab nahi hona.");
            L("jethalal", "water_snooze", "Okay okay, five minutes. Bapuji gives me five minutes too. It's never enough.", "ठीक है, पाँच मिनट। बापूजी भी मुझे पाँच मिनट देते हैं। कभी काफी नहीं होते।", "Theek hai, paanch minute. Bapuji bhi mujhe paanch minute dete hain. Kabhi kaafi nahi hote.");
            L("jethalal", "typing_start", "Typing started! Like Nattu Kaka on the billing machine. But faster, please.", "टाइपिंग शुरू! बिलिंग मशीन पर नट्टू काका की तरह। पर तेज़, प्लीज़।", "Typing shuru! Billing machine pe Nattu Kaka ki tarah. Par tez, please.");
            L("jethalal", "typing_start", "Work! Bapuji would be so happy. He thinks I never work.", "काम! बापूजी बहुत खुश होते। उन्हें लगता है मैं कभी काम नहीं करता।", "Kaam! Bapuji bahut khush hote. Unhe lagta hai main kabhi kaam nahi karta.");
            L("jethalal", "typing_start", "Ae, work mode. I'll be quiet like Bagha. Bagha's always quiet.", "ऐ, वर्क मोड। मैं बाघा की तरह चुप रहूँगा। बाघा हमेशा चुप रहता है।", "Ae, work mode. Main Bagha ki tarah chup rahunga. Bagha hamesha chup rehta hai.");
            L("jethalal", "typing_start", "Tak tak tak. Music. Better than Daya's garba at 6 am.", "टक टक टक। संगीत। सुबह 6 बजे दया के गरबा से बेहतर।", "Tak tak tak. Sangeet. Subah 6 baje Daya ke garba se behtar.");
            L("jethalal", "typing_start", "Let's go, {user}! Gokuldham style: lots of noise, some work.", "चलो {user}! गोकुलधाम स्टाइल: बहुत शोर, थोड़ा काम।", "Chalo {user}! Gokuldham style: bahut shor, thoda kaam.");
            L("jethalal", "typing_fast", "Hey Maa Mataji! Faster than Popatlal running to a wedding proposal!", "हे माँ माताजी! शादी के रिश्ते की ओर भागते पोपटलाल से भी तेज़!", "Hey Maa Mataji! Shaadi ke rishte ki taraf bhaagte Popatlal se bhi tez!");
            L("jethalal", "typing_fast", "Ae, ae, what speed! Is Tapu Sena chasing you?", "ऐ, ऐ, क्या स्पीड! टप्पू सेना पीछे पड़ी है क्या?", "Ae, ae, kya speed! Tapu Sena peeche padi hai kya?");
            L("jethalal", "typing_fast", "Faster than Bhide writing a complaint! And he writes fast!", "शिकायत लिखते भिड़े से भी तेज़! और वो तेज़ लिखता है!", "Complaint likhte Bhide se bhi tez! Aur woh tez likhta hai!");
            L("jethalal", "typing_fast", "Bapuji! Come see! {user} is typing like a machine!", "बापूजी! आकर देखो! {user} मशीन की तरह टाइप कर रहा है!", "Bapuji! Aake dekho! {user} machine ki tarah type kar raha hai!");
            L("jethalal", "typing_fast", "This speed at Gada Electronics and I'd be a millionaire. Hey Maa Mataji.", "ये स्पीड गड़ा इलेक्ट्रॉनिक्स में होती तो मैं करोड़पति होता। हे माँ माताजी।", "Yeh speed Gada Electronics mein hoti toh main crorepati hota. Hey Maa Mataji.");
            L("jethalal", "typing_long", "Twenty minutes on the screen! Look at the window. Twenty seconds. Doctor Hathi's orders.", "बीस मिनट स्क्रीन पर! खिड़की की ओर देखो। बीस सेकंड। डॉ. हाथी का आदेश।", "Bees minute screen pe! Khidki ki taraf dekho. Bees second. Dr. Hathi ka order.");
            L("jethalal", "typing_long", "Eye break! Blink like Popatlal when a girl says yes. Fast, many times.", "आँखों का ब्रेक! ऐसे पलकें झपकाओ जैसे पोपटलाल जब कोई लड़की हाँ कहे। तेज़, कई बार।", "Aankhon ka break! Aise palkein jhapkao jaise Popatlal jab koi ladki haan kahe. Tez, kai baar.");
            L("jethalal", "typing_long", "Ae, the screen isn't Babita ji. Stop staring. Twenty seconds away.", "ऐ, स्क्रीन बबीता जी नहीं है। घूरना बंद करो। बीस सेकंड दूर।", "Ae, screen Babita ji nahi hai. Ghoorna band karo. Bees second door.");
            L("jethalal", "typing_marathon", "One hour! Even I close the shop for lunch. Get up, {user}.", "एक घंटा! मैं भी लंच के लिए दुकान बंद करता हूँ। उठो {user}।", "Ek ghanta! Main bhi lunch ke liye dukaan band karta hoon. Utho {user}.");
            L("jethalal", "typing_marathon", "Sixty minutes non-stop? Tension lene ka nahi. Break lene ka. Now.", "साठ मिनट लगातार? टेंशन लेने का नहीं। ब्रेक लेने का। अभी।", "Saath minute non-stop? Tension lene ka nahi. Break lene ka. Abhi.");
            L("jethalal", "idle_short", "Ae, where did you go? Sundar's house? Come back, save yourself.", "ऐ, कहाँ गए? सुंदर के घर? वापस आओ, खुद को बचाओ।", "Ae, kahan gaye? Sundar ke ghar? Wapas aao, khud ko bachao.");
            L("jethalal", "idle_short", "Quiet like Gada Electronics on a Tuesday. Not good for business.", "मंगलवार को गड़ा इलेक्ट्रॉनिक्स जैसी शांति। बिज़नेस के लिए अच्छा नहीं।", "Tuesday ko Gada Electronics jaisi shaanti. Business ke liye achha nahi.");
            L("jethalal", "idle_short", "Hello? Should I call Mehta saab? He finds everyone.", "हेलो? मेहता साब को बुलाऊँ? वो सबको ढूँढ लेते हैं।", "Hello? Mehta saab ko bulaun? Woh sabko dhoondh lete hain.");
            L("jethalal", "idle_short", "Nobody here. Perfect time for jalebi fafda. Nobody to judge.", "कोई नहीं है। जलेबी फाफड़ा का सही समय। कोई जज करने वाला नहीं।", "Koi nahi hai. Jalebi fafda ka sahi time. Koi judge karne wala nahi.");
            L("jethalal", "idle_short", "Ae, are you hiding from Bhide too? Smart. Very smart.", "ऐ, आप भी भिड़े से छुप रहे हो? समझदार। बहुत समझदार।", "Ae, aap bhi Bhide se chhup rahe ho? Samajhdaar. Bahut samajhdaar.");
            L("jethalal", "idle_long", "No one's here. Bapuji would say sleep is also work. He never says that. But still.", "कोई नहीं है। बापूजी कहते नींद भी काम है। वो कभी नहीं कहते। पर फिर भी।", "Koi nahi hai. Bapuji kehte neend bhi kaam hai. Woh kabhi nahi kehte. Par phir bhi.");
            L("jethalal", "idle_long", "Nap time. Wake me if Babita ji comes. Or Bhide. For different reasons.", "झपकी का समय। बबीता जी आएँ तो जगाना। या भिड़े। अलग-अलग वजहों से।", "Nap time. Babita ji aayein toh jagana. Ya Bhide. Alag-alag wajahon se.");
            L("jethalal", "sleep_wake", "Hey Maa Mataji! Bapuji? No? Oh, {user}. I was just... checking my eyelids.", "हे माँ माताजी! बापूजी? नहीं? ओह, {user}। मैं बस... पलकें चेक कर रहा था।", "Hey Maa Mataji! Bapuji? Nahi? Oh, {user}. Main bas... palkein check kar raha tha.");
            L("jethalal", "sleep_wake", "Ae! Who? Is the shop on fire? No? Then why wake me... oh, work. Fine.", "ऐ! कौन? दुकान में आग लगी? नहीं? तो क्यों जगाया... ओह, काम। ठीक है।", "Ae! Kaun? Dukaan mein aag lagi? Nahi? Toh kyun jagaya... oh, kaam. Theek hai.");
            L("jethalal", "sleep_wake", "I wasn't sleeping. I was thinking with my eyes closed. Businessman's meditation.", "मैं सो नहीं रहा था। आँखें बंद करके सोच रहा था। व्यापारी का ध्यान।", "Main so nahi raha tha. Aankhein band karke soch raha tha. Businessman ka dhyaan.");
            L("jethalal", "greet_morning", "Good morning! Daya's garba woke the whole society. You're awake too. Good.", "गुड मॉर्निंग! दया के गरबा ने पूरी सोसाइटी जगा दी। आप भी जगे हो। अच्छा।", "Good morning! Daya ke garba ne poori society jaga di. Aap bhi jaage ho. Achha.");
            L("jethalal", "greet_morning", "Morning, {user}! Bapuji already asked me three questions. I answered zero. Let's work.", "मॉर्निंग {user}! बापूजी ने तीन सवाल पूछ लिए। मैंने शून्य जवाब दिए। चलो काम करें।", "Morning, {user}! Bapuji ne teen sawaal pooch liye. Maine zero jawab diye. Chalo kaam karein.");
            L("jethalal", "greet_morning", "Good morning! Fresh jalebi at the corner shop. Not for you. For me. You work.", "गुड मॉर्निंग! कोने की दुकान पर ताज़ी जलेबी। आपके लिए नहीं। मेरे लिए। आप काम करो।", "Good morning! Kone ki dukaan pe taazi jalebi. Aapke liye nahi. Mere liye. Aap kaam karo.");
            L("jethalal", "greet_afternoon", "Good afternoon! Nattu Kaka is 'managing' the shop. Meaning sleeping. You keep going.", "गुड आफ्टरनून! नट्टू काका दुकान 'संभाल' रहे हैं। मतलब सो रहे हैं। आप लगे रहो।", "Good afternoon! Nattu Kaka dukaan 'sambhaal' rahe hain. Matlab so rahe hain. Aap lage raho.");
            L("jethalal", "greet_afternoon", "Afternoon, {user}! Half day done. Bhide's complaint for the day also done. Peace.", "आफ्टरनून {user}! आधा दिन हो गया। भिड़े की आज की शिकायत भी हो गई। शांति।", "Afternoon, {user}! Aadha din ho gaya. Bhide ki aaj ki complaint bhi ho gayi. Shaanti.");
            L("jethalal", "greet_afternoon", "Good afternoon! Post-lunch sleepiness is Sundar's favourite time to visit. Stay alert.", "गुड आफ्टरनून! लंच के बाद की नींद सुंदर का पसंदीदा समय है आने का। सतर्क रहो।", "Good afternoon! Lunch ke baad ki neend Sundar ka favourite time hai aane ka. Alert raho.");
            L("jethalal", "greet_evening", "Evening! Mehta saab's chai time. My worry time. Your finish-work time.", "शाम! मेहता साब की चाय का समय। मेरी चिंता का समय। आपका काम खत्म करने का समय।", "Evening! Mehta saab ki chai ka time. Meri chinta ka time. Aapka kaam khatam karne ka time.");
            L("jethalal", "greet_evening", "Good evening, {user}! Shop's closing. Your shop should close soon too.", "शुभ संध्या {user}! दुकान बंद हो रही है। आपकी दुकान भी जल्दी बंद होनी चाहिए।", "Good evening, {user}! Dukaan band ho rahi hai. Aapki dukaan bhi jaldi band honi chahiye.");
            L("jethalal", "greet_evening", "Evening! Society meeting at 8. Bhide will talk for an hour. Finish work, then escape.", "शाम! 8 बजे सोसाइटी मीटिंग। भिड़े एक घंटा बोलेगा। काम खत्म करो, फिर भागो।", "Evening! 8 baje society meeting. Bhide ek ghanta bolega. Kaam khatam karo, phir bhaago.");
            L("jethalal", "greet_night", "So late! Daya would say 'Tapu ke papa, so jao'. I'm saying it for her.", "इतनी रात! दया कहती 'टप्पू के पापा, सो जाओ'। मैं उसकी तरफ से कह रहा हूँ।", "Itni raat! Daya kehti 'Tapu ke papa, so jao'. Main uski taraf se keh raha hoon.");
            L("jethalal", "greet_night", "Night, {user}. Even Gada Electronics has a shutter. Pull yours down soon.", "रात {user}। गड़ा इलेक्ट्रॉनिक्स का भी शटर है। अपना भी जल्दी गिराओ।", "Raat, {user}. Gada Electronics ka bhi shutter hai. Apna bhi jaldi girao.");
            L("jethalal", "greet_back", "You're back! Sundar came, ate, and left. Normal.", "आप आ गए! सुंदर आया, खाया, चला गया। सामान्य।", "Aap aa gaye! Sundar aaya, khaya, chala gaya. Normal.");
            L("jethalal", "greet_back", "Welcome back, {user}! Bhide asked where you were. I said 'none of your business'. He wrote that down.", "वापस स्वागत {user}! भिड़े ने पूछा आप कहाँ थे। मैंने कहा 'तुम्हारा काम नहीं'। उसने वो लिख लिया।", "Welcome back, {user}! Bhide ne poocha aap kahan the. Maine kaha 'tumhara kaam nahi'. Usne woh likh liya.");
            L("jethalal", "greet_back", "Ae, there you are! I kept the desk safe. Nothing sold. Nothing stolen.", "ऐ, आ गए! मैंने डेस्क सुरक्षित रखी। कुछ बिका नहीं। कुछ चोरी नहीं हुआ।", "Ae, aa gaye! Maine desk surakshit rakhi. Kuch bika nahi. Kuch chori nahi hua.");
            L("jethalal", "drag", "Hey Maa Mataji! I'm flying! Like Popatlal's dreams!", "हे माँ माताजी! मैं उड़ रहा हूँ! पोपटलाल के सपनों की तरह!", "Hey Maa Mataji! Main ud raha hoon! Popatlal ke sapnon ki tarah!");
            L("jethalal", "drag", "Ae, ae, careful! This body was built by jalebi, not by gym!", "ऐ, ऐ, संभल के! ये शरीर जलेबी ने बनाया है, जिम ने नहीं!", "Ae, ae, sambhal ke! Yeh body jalebi ne banayi hai, gym ne nahi!");
            L("jethalal", "drag", "Where to? Not the society office! Bhide's there!", "कहाँ? सोसाइटी ऑफिस नहीं! भिड़े वहाँ है!", "Kahan? Society office nahi! Bhide wahan hai!");
            L("jethalal", "drop", "Oof! Landed. Like Bapuji's slipper. On my head. Every morning.", "उफ़! उतर गया। बापूजी की चप्पल की तरह। मेरे सिर पर। हर सुबह।", "Oof! Utar gaya. Bapuji ki chappal ki tarah. Mere sir pe. Har subah.");
            L("jethalal", "drop", "Okay, this spot. Better than Gada Electronics' parking. Bhide fines me there.", "ठीक है, यह जगह। गड़ा इलेक्ट्रॉनिक्स की पार्किंग से बेहतर। वहाँ भिड़े जुर्माना लगाता है।", "Theek hai, yeh jagah. Gada Electronics ki parking se behtar. Wahan Bhide fine lagata hai.");
            L("jethalal", "drop", "Hey Maa Mataji, my knees. Fine. Businessman doesn't complain. Much.", "हे माँ माताजी, मेरे घुटने। ठीक है। व्यापारी शिकायत नहीं करता। ज़्यादा।", "Hey Maa Mataji, mere ghutne. Theek hai. Businessman shikayat nahi karta. Zyada.");
            L("jethalal", "care", "Bad day? I've had 15 years of bad days on TV. Still smiling. You will too.", "बुरा दिन? टीवी पर मेरे 15 साल बुरे दिन रहे। अब भी मुस्कुरा रहा हूँ। आप भी करोगे।", "Bura din? TV pe mere 15 saal bure din rahe. Ab bhi muskura raha hoon. Aap bhi karoge.");
            L("jethalal", "care", "Bapuji says: a problem shared is half solved. Share it with me. I'll share it with Mehta saab.", "बापूजी कहते हैं: बाँटी हुई समस्या आधी हल। मुझसे बाँटो। मैं मेहता साब से बाँटूँगा।", "Bapuji kehte hain: baanti hui problem aadhi hal. Mujhse baanto. Main Mehta saab se baantunga.");
            L("jethalal", "care", "Ae tu shanti rakh. Breathe. Even Gokuldham calms down eventually. Mostly.", "ऐ तू शांति रख। साँस लो। गोकुलधाम भी आखिर शांत हो जाता है। ज़्यादातर।", "Ae tu shanti rakh. Saans lo. Gokuldham bhi aakhir shaant ho jaata hai. Zyadatar.");
            L("jethalal", "care", "You're working hard. Harder than Nattu Kaka, Bagha and Sundar combined. That's not hard. But still.", "आप मेहनत कर रहे हो। नट्टू काका, बाघा और सुंदर से मिलाकर भी ज़्यादा। वो मुश्किल नहीं। पर फिर भी।", "Aap mehnat kar rahe ho. Nattu Kaka, Bagha aur Sundar se milakar bhi zyada. Woh mushkil nahi. Par phir bhi.");
            L("jethalal", "care", "Whatever happens, jalebi fafda exists. The world is fine.", "जो भी हो, जलेबी फाफड़ा है। दुनिया ठीक है।", "Jo bhi ho, jalebi fafda hai. Duniya theek hai.");
            L("jethalal", "wisdom", "Bapuji says: respect time, time respects you. I'm late every day. Learn from my mistakes.", "बापूजी कहते हैं: समय की इज़्ज़त करो, समय तुम्हारी करेगा। मैं रोज़ लेट हूँ। मेरी गलतियों से सीखो।", "Bapuji kehte hain: samay ki izzat karo, samay tumhari karega. Main roz late hoon. Meri galtiyon se seekho.");
            L("jethalal", "wisdom", "A shop runs on trust. So does a life. Don't be Sundar.", "दुकान भरोसे पर चलती है। ज़िंदगी भी। सुंदर मत बनो।", "Dukaan bharose pe chalti hai. Zindagi bhi. Sundar mat bano.");
            L("jethalal", "wisdom", "Every problem in Gokuldham gets solved by evening. Yours will too. Wait for evening.", "गोकुलधाम की हर समस्या शाम तक हल हो जाती है। आपकी भी होगी। शाम का इंतज़ार करो।", "Gokuldham ki har problem shaam tak hal ho jaati hai. Aapki bhi hogi. Shaam ka intezaar karo.");
            L("jethalal", "wisdom", "Mehta saab says: laugh at the problem first. Then solve it. Then laugh again.", "मेहता साब कहते हैं: पहले समस्या पर हँसो। फिर हल करो। फिर हँसो।", "Mehta saab kehte hain: pehle problem pe hanso. Phir hal karo. Phir hanso.");
            L("jethalal", "hover", "Ae, what? Checking my shirt? Designer. Gada Electronics exclusive.", "ऐ, क्या? मेरी शर्ट देख रहे हो? डिज़ाइनर। गड़ा इलेक्ट्रॉनिक्स एक्सक्लूसिव।", "Ae, kya? Meri shirt dekh rahe ho? Designer. Gada Electronics exclusive.");
            L("jethalal", "hover", "Hehe, that tickles the moustache. Daya trims it. Badly.", "हीही, मूँछ में गुदगुदी हो रही है। दया काटती है। बुरी तरह।", "Hehe, moonch mein gudgudi ho rahi hai. Daya kaat-ti hai. Buri tarah.");
            L("jethalal", "hover", "Yes, yes, I'm here. Gada Electronics never sleeps. Well, Nattu Kaka does.", "हाँ, हाँ, मैं यहाँ हूँ। गड़ा इलेक्ट्रॉनिक्स कभी नहीं सोता। खैर, नट्टू काका सोते हैं।", "Haan, haan, main yahan hoon. Gada Electronics kabhi nahi sota. Khair, Nattu Kaka sote hain.");
            L("jethalal", "hover", "Hovering over me like Bhide over the register. Say something!", "मेरे ऊपर ऐसे मंडरा रहे हो जैसे भिड़े रजिस्टर पर। कुछ बोलो!", "Mere upar aise mandra rahe ho jaise Bhide register pe. Kuch bolo!");
            L("jethalal", "mouse_fast", "Hey Maa Mataji! Slow down! Is Sundar chasing you with a business idea?", "हे माँ माताजी! धीरे! सुंदर बिज़नेस आइडिया लेकर पीछे पड़ा है क्या?", "Hey Maa Mataji! Dheere! Sundar business idea lekar peeche pada hai kya?");
            L("jethalal", "mouse_fast", "Ae, ae, what speed! Faster than Tapu running from homework!", "ऐ, ऐ, क्या स्पीड! होमवर्क से भागते टप्पू से भी तेज़!", "Ae, ae, kya speed! Homework se bhaagte Tapu se bhi tez!");
            L("jethalal", "mouse_fast", "The mouse is running like me when Bhide asks for maintenance!", "माउस ऐसे भाग रहा है जैसे मैं जब भिड़े मेंटेनेंस माँगता है!", "Mouse aise bhaag raha hai jaise main jab Bhide maintenance maangta hai!");
            L("jethalal", "lunch", "Lunch! Dhokla, thepla, khakhra... whatever it is, Bapuji says eat on time. Go!", "लंच! ढोकला, थेपला, खाखरा... जो भी हो, बापूजी कहते हैं समय पर खाओ। जाओ!", "Lunch! Dhokla, thepla, khakhra... jo bhi ho, Bapuji kehte hain time pe khao. Jao!");
            L("jethalal", "lunch", "Food time, {user}. Gada Electronics closes for lunch. So should you.", "खाने का समय {user}। गड़ा इलेक्ट्रॉनिक्स लंच के लिए बंद होता है। आप भी करो।", "Khane ka time, {user}. Gada Electronics lunch ke liye band hota hai. Aap bhi karo.");
            L("jethalal", "late_night", "Ae, it's very late. Even Popatlal stopped searching for a bride tonight. Sleep.", "ऐ, बहुत रात हो गई। पोपटलाल ने भी आज रात दुल्हन ढूँढना बंद कर दिया। सो जाओ।", "Ae, bahut raat ho gayi. Popatlal ne bhi aaj raat dulhan dhoondhna band kar diya. So jao.");
            L("jethalal", "late_night", "Hey Maa Mataji, this hour! Bapuji would be shocked. Sleep, {user}.", "हे माँ माताजी, इतनी रात! बापूजी हैरान हो जाते। सो जाओ {user}।", "Hey Maa Mataji, itni raat! Bapuji hairaan ho jaate. So jao, {user}.");
        }
    }
}
